    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed
        
        String inputText=jTextArea3.getText();
        
        textLength = inputText.length();
        jTextField1.setText(String.valueOf(textLength));
        
        
       tabCount=inputText.split("\t",-1).length-1;
       jTextField3.setText(String.valueOf(tabCount));
       
        lineCount = textLength>0 ? inputText.split("\n",-1).length:0;
        jTextField2.setText(String.valueOf(lineCount));
        
       spaceCount = inputText.split(" ",-1).length-1;
        jTextField4.setText(String.valueOf( spaceCount));
        
        wordCount=Word_Count(inputText);
         jTextField5.setText(String.valueOf( wordCount));
        
        
        // TODO add your handling code here:
    }//GEN-LAST:event_jButton1ActionPerformed

